using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BaseDecreaseActivationAmountEffect", menuName = "Data/Battle/Effects/Orion/BaseDecreaseActivationAmount Effect")]
public class BaseDecreaseActivationAmountEffect : Effect
{
	public enum BaseDecreaseActivationAmountEffectType
	{
		KARMA,
		ASTRIUM,
		KARMACORRUPTION
	}

	private const string baseDecreaseActivationAmountID = "BaseDecreaseActivationAmount";

	[Header("Base Decrease Activation Amount Effect")]
	[SerializeField]
	private BaseDecreaseActivationAmountEffectType baseDecreaseActivationAmountEffectType;

	[SerializeField]
	private Effect effect;

	protected override string GetLocalizedDescription()
	{
		if (baseDecreaseActivationAmountEffectType == BaseDecreaseActivationAmountEffectType.KARMACORRUPTION)
		{
			return base.GetLocalizedDescription();
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("BaseDecreaseActivationAmount");
	}

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		int num = ((baseDecreaseActivationAmountEffectType == BaseDecreaseActivationAmountEffectType.KARMA) ? ((effect as KarmaEffect).AmountToTriggerKarma - base.MaxEffectAmount) : ((baseDecreaseActivationAmountEffectType != BaseDecreaseActivationAmountEffectType.ASTRIUM) ? 1 : ((effect as AstriumEffect).AmountToTriggerAstrium - base.MaxEffectAmount)));
		localizedDescription = ((amount == EffectsValues.NO_VALUE) ? ((baseDecreaseActivationAmountEffectType != BaseDecreaseActivationAmountEffectType.KARMACORRUPTION) ? GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, effect.GetEffectName(), GetNumberToReplaceWithX(), num) : GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), num)) : ((baseDecreaseActivationAmountEffectType != BaseDecreaseActivationAmountEffectType.KARMACORRUPTION) ? Smart.Format(localizedDescription, effect.GetEffectName(), amount, num) : Smart.Format(localizedDescription, amount, num)));
		return localizedDescription + AppendedDescription();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (baseDecreaseActivationAmountEffectType != BaseDecreaseActivationAmountEffectType.KARMACORRUPTION)
		{
			effectOwner.GetComponent<UnitEffects>().IsEffectActiveWithActivation(effect, activateFeedback: false, updateAmount: false);
		}
	}
}
